# Thêm vào items cho đến khi đủ ít nhất 505 từ
added_count = 0
existing_words = {it["text"] for it in items}

for word_info in NEW_WORDS:
    text, ipa, meaning, example, ex_meaning, note, topic = word_info
    if text not in existing_words:
        items.append({
            "id": f"adv-{len(items) + 1}",
            "type": "vocab",
            "text": text,
            "ipa": ipa,
            "meaning": meaning,
            "topic": topic,
            "example": example,
            "exampleMeaning": ex_meaning,
            "note": note,
            "status": "new",
            "dateAdded": "2026-10-08"
        })
        existing_words.add(text)
        added_count += 1
        if len(items) >= 505:
            break

# Cập nhật ID tuần tự từ adv-1 đến adv-505
for idx, it in enumerate(items):
    it["id"] = f"adv-{idx + 1}"

topics = []
for it in items:
    if it["topic"] not in topics:
        topics.append(it["topic"])

